  5	/** Opens the SQLite database shared by the server and worker processes. */
  6	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  7	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  8	  const db = new DatabaseSync(path);
  9	  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
 10	  // open the same database at once, so the loser must wait rather than fail.
 11	  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
 12	  return db;
 13	}
