 15	/** Creates the tables both processes use. Safe to run from each process at startup. */
 16	export function initSchema(db: DatabaseSync): void {
 17	  db.exec(`
 18	    CREATE TABLE IF NOT EXISTS jobs (
 19	      seq INTEGER PRIMARY KEY AUTOINCREMENT,
 20	      id TEXT NOT NULL UNIQUE,
 21	      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
 22	      input TEXT NOT NULL,
 23	      steps INTEGER NOT NULL,
 24	      fail_attempts INTEGER NOT NULL,
 25	      attempts INTEGER NOT NULL DEFAULT 0,
 26	      progress_completed INTEGER NOT NULL DEFAULT 0,
 27	      result_output TEXT,
 28	      error TEXT,
 29	      run_after INTEGER NOT NULL DEFAULT 0,
 30	      created_at TEXT NOT NULL,
 31	      updated_at TEXT NOT NULL
 32	    );
 33	    CREATE INDEX IF NOT EXISTS jobs_by_status ON jobs (status, run_after, seq);
 34	    CREATE TABLE IF NOT EXISTS idempotency_keys (
 35	      key TEXT PRIMARY KEY,
 36	      fingerprint TEXT NOT NULL,
 37	      job_id TEXT NOT NULL REFERENCES jobs (id)
 38	    );
 39	    CREATE TABLE IF NOT EXISTS worker_heartbeat (
 40	      name TEXT PRIMARY KEY,
 41	      pid INTEGER NOT NULL,
 42	      seen_at INTEGER NOT NULL
 43	    );
 44	  `);
 45	}
