 47	/** Runs `fn` inside a write transaction that takes the write lock up front. */
 48	export function transaction<T>(db: DatabaseSync, fn: () => T): T {
 49	  db.exec('BEGIN IMMEDIATE');
 50	  let result: T;
 51	  try {
 52	    result = fn();
 53	  } catch (e) {
 54	    db.exec('ROLLBACK');
 55	    throw e;
 56	  }
 57	  db.exec('COMMIT');
 58	  return result;
 59	}
