 30	/** The public JSON shape of a job. */
 31	export interface Job {
 32	  id: string;
 33	  status: JobRow['status'];
 34	  input: string;
 35	  steps: number;
 36	  failAttempts: number;
 37	  attempts: number;
 38	  progress: { completed: number; total: number };
 39	  result: { output: string } | null;
 40	  error: string | null;
 41	  createdAt: string;
 42	  updatedAt: string;
 43	}
 44	
 45	export function nowIso(): string {
 46	  return new Date().toISOString();
 47	}
 48	
 49	export function toJob(row: JobRow): Job {
 50	  return {
 51	    id: row.id,
 52	    status: row.status,
 53	    input: row.input,
 54	    steps: row.steps,
 55	    failAttempts: row.fail_attempts,
 56	    attempts: row.attempts,
 57	    progress: { completed: row.progress_completed, total: row.steps },
 58	    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
 59	    error: row.status === 'failed' ? row.error : null,
 60	    createdAt: row.created_at,
 61	    updatedAt: row.updated_at,
 62	  };
 63	}
