 65	/** Typed wrapper around `prepare().get()`, which returns loosely typed records. */
 66	export function one<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T | undefined {
 67	  return db.prepare(sql).get(...params) as unknown as T | undefined;
 68	}
