 70	export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
 71	  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
 72	}
 73	
 74	export function listJobRows(db: DatabaseSync): JobRow[] {
 75	  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
 76	}
