 78	export type SubmitResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };
 79	
 80	/**
 81	 * Creates a job, or, when an idempotency key is given, replays the job created with that key.
 82	 * The check and the insert share one transaction, so a key never yields two jobs.
 83	 */
 84	export function submitJob(db: DatabaseSync, input: NewJob, key: string | undefined): SubmitResult {
 85	  const fingerprint = JSON.stringify([input.input, input.steps, input.failAttempts]);
 86	  return transaction(db, (): SubmitResult => {
 87	    if (key !== undefined) {
 88	      const existing = one<{ fingerprint: string; job_id: string }>(
 89	        db,
 90	        'SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?',
 91	        key,
 92	      );
 93	      if (existing) {
 94	        if (existing.fingerprint !== fingerprint) return { kind: 'conflict' };
 95	        const row = getJobRow(db, existing.job_id);
 96	        if (!row) throw new Error(`idempotency key ${key} refers to a missing job`);
 97	        return { kind: 'replayed', job: toJob(row) };
 98	      }
 99	    }
100	    const id = randomUUID();
101	    const now = nowIso();
102	    db.prepare(
103	      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, created_at, updated_at)
104	       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
105	    ).run(id, input.input, input.steps, input.failAttempts, now, now);
106	    if (key !== undefined) {
107	      db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)').run(key, fingerprint, id);
108	    }
109	    const row = getJobRow(db, id);
110	    if (!row) throw new Error('inserted job not found');
111	    return { kind: 'created', job: toJob(row) };
112	  });
113	}
