  6	/** How often the worker writes its heartbeat. */
  7	const HEARTBEAT_MS = 1000;
  8	/** How long an idle worker waits before checking the queue again. */
  9	const IDLE_MS = 200;
 10	
 11	const db = openDatabase();
 12	initSchema(db);
 13	
 14	let stopping = false;
 15	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
 16	  process.on(signal, () => {
 17	    stopping = true;
 18	  });
 19	}
 20	
 21	let lastBeat = 0;
 22	function heartbeat(force = false): void {
 23	  const now = Date.now();
 24	  if (!force && now - lastBeat < HEARTBEAT_MS) return;
 25	  lastBeat = now;
 26	  db.prepare(
 27	    `INSERT INTO worker_heartbeat (name, pid, seen_at) VALUES ('worker', ?, ?)
 28	     ON CONFLICT (name) DO UPDATE SET pid = excluded.pid, seen_at = excluded.seen_at`,
 29	  ).run(process.pid, now);
 30	}
