 32	/**
 33	 * Jobs left `running` by a worker that died are queued again. Their interrupted attempt still
 34	 * counts in `attempts`, which is the number of attempts started.
 35	 */
 36	function recoverInterrupted(database: DatabaseSync): number {
 37	  return database
 38	    .prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'")
 39	    .run(nowIso()).changes as number;
 40	}
 41	
 42	/** Takes the oldest queued job that is due and starts an attempt on it. */
 43	function claimNext(database: DatabaseSync): JobRow | undefined {
 44	  return transaction(database, (): JobRow | undefined => {
 45	    const row = one<JobRow>(
 46	      database,
 47	      "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
 48	      Date.now(),
 49	    );
 50	    if (!row) return undefined;
 51	    database
 52	      .prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?")
 53	      .run(nowIso(), row.seq);
 54	    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
 55	  });
 56	}
 57	
 58	function setProgress(seq: number, completed: number): void {
 59	  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?').run(completed, nowIso(), seq);
 60	}
 61	
 62	function complete(job: JobRow): void {
 63	  db.prepare(
 64	    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?",
 65	  ).run(job.input.toUpperCase(), nowIso(), job.seq);
 66	}
 67	
 68	function fail(job: JobRow, error: string): void {
 69	  db.prepare("UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, updated_at = ? WHERE seq = ?").run(error, nowIso(), job.seq);
 70	}
 71	
 72	function requeueAfterDelay(job: JobRow): void {
 73	  db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE seq = ?").run(Date.now() + RETRY_DELAY_MS, nowIso(), job.seq);
 74	}
 75	
 76	/**
 77	 * Runs one attempt. Returns early without changing the job when the worker is stopping, so the
 78	 * job stays `running` and is processed again after the next start.
 79	 */
 80	async function runAttempt(job: JobRow): Promise<void> {
 81	  if (job.attempts <= job.fail_attempts) {
 82	    // The simulated dependency fails at the first step, before any progress is made.
 83	    await sleep(STEP_MS);
 84	    if (stopping) return;
 85	    if (job.attempts >= MAX_ATTEMPTS) fail(job, 'transient failure');
 86	    else requeueAfterDelay(job);
 87	    return;
 88	  }
 89	  for (let done = 1; done <= job.steps; done++) {
 90	    await sleep(STEP_MS);
 91	    if (stopping) return;
 92	    setProgress(job.seq, done);
 93	    heartbeat();
 94	  }
 95	  complete(job);
 96	}
 97	
 98	async function main(): Promise<void> {
 99	  heartbeat(true);
100	  const recovered = recoverInterrupted(db);
101	  console.log(`worker started (recovered ${recovered} interrupted job(s))`);
102	
103	  while (!stopping) {
104	    heartbeat();
105	    try {
106	      const job = claimNext(db);
107	      if (job) await runAttempt(job);
108	      else await sleep(IDLE_MS);
109	    } catch (e) {
110	      console.error('worker error:', e);
111	      await sleep(IDLE_MS);
112	    }
113	  }
114	
115	  db.prepare("DELETE FROM worker_heartbeat WHERE name = 'worker'").run();
116	  db.close();
117	  console.log('worker stopped');
118	}
119	
120	await main();

