     7	/** A worker heartbeat older than this means the worker is down. */
     8	const WORKER_STALE_MS = 3000;
     9	/** Bodies larger than this are rejected; valid requests are far smaller. */
    10	const MAX_BODY_BYTES = 64 * 1024;
    11	
    12	const db = openDatabase();
    13	initSchema(db);
    14	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
    15	
    16	function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
    17	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
    18	  res.end(JSON.stringify(body));
    19	}
    20	
    21	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
    22	  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
    23	}
    24	
    25	function readBody(req: IncomingMessage): Promise<string | undefined> {
    26	  return new Promise((resolve, reject) => {
    27	    const chunks: Buffer[] = [];
    28	    let size = 0;
    29	    let tooLarge = false;
    30	    req.on('data', (chunk: Buffer) => {
    31	      size += chunk.length;
    32	      if (size > MAX_BODY_BYTES) tooLarge = true;
    33	      else chunks.push(chunk);
    34	    });
    35	    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    36	    req.on('error', reject);
    37	  });
    38	}
    39	
    40	function workerIsUp(): boolean {
    41	  const row = one<{ seen_at: number }>(db, "SELECT seen_at FROM worker_heartbeat WHERE name = 'worker'");
    42	  return row !== undefined && Date.now() - row.seen_at <= WORKER_STALE_MS;
    43	}
