    45	async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
    46	  const rawKey = req.headers['idempotency-key'];
    47	  const key = typeof rawKey === 'string' ? rawKey : undefined;
    48	  const keyError = validateIdempotencyKey(key);
    49	  const raw = await readBody(req);
    50	  const parsed = parseCreateJob(req.headers['content-type'], raw);
    51	  const fields = [...(keyError ? [keyError] : []), ...(parsed.ok ? [] : parsed.fields)];
    52	  if (fields.length > 0 || !parsed.ok) {
    53	    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
    54	  }
    55	  const result = submitJob(db, parsed.value, key);
    56	  if (result.kind === 'conflict') {
    57	    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    58	  }
    59	  send(res, result.kind === 'created' ? 201 : 200, result.job);
    60	}
    61	
    62	async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
    63	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    64	  const method = req.method ?? 'GET';
    65	  const methodNotAllowed = (allow: string) =>
    66	    send(res, 405, { error: { code: 'method_not_allowed', message: `Use ${allow} for this path.` } }, { allow });
    67	
    68	  if (pathname === '/health') {
    69	    if (method !== 'GET') return methodNotAllowed('GET');
    70	    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
    71	  }
    72	  if (pathname === '/') {
    73	    if (method !== 'GET') return methodNotAllowed('GET');
    74	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    75	    res.end(uiHtml);
    76	    return;
    77	  }
    78	  if (pathname === '/api/jobs') {
    79	    if (method === 'GET') {
    80	      return send(res, 200, { jobs: listJobRows(db).map(toJob) });
    81	    }
    82	    if (method === 'POST') return createJobRoute(req, res);
    83	    return methodNotAllowed('GET, POST');
    84	  }
    85	  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    86	  if (match) {
    87	    if (method !== 'GET') return methodNotAllowed('GET');
    88	    let id: string;
    89	    try {
    90	      id = decodeURIComponent(match[1]!);
    91	    } catch {
    92	      return sendError(res, 404, 'not_found', 'No such job.');
    93	    }
    94	    const row = getJobRow(db, id);
    95	    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    96	    return send(res, 200, toJob(row));
    97	  }
    98	  sendError(res, 404, 'not_found', 'No such path.');
    99	}
