     2	  input: string;
     3	  steps: number;
     4	  failAttempts: number;
     5	}
     6	
     7	export interface FieldError {
     8	  field: string;
     9	  message: string;
    10	}
    11	
    12	export type Parsed<T> = { ok: true; value: T } | { ok: false; fields: FieldError[] };
    13	
    14	const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
    15	const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
    16	
    17	/** Returns the Idempotency-Key error, or undefined when the key is absent or valid. */
    18	export function validateIdempotencyKey(key: string | undefined): FieldError | undefined {
    19	  if (key === undefined || KEY_PATTERN.test(key)) return undefined;
    20	  return { field: 'Idempotency-Key', message: 'must be 1 to 128 characters: letters, digits, "_" or "-"' };
    21	}
    22	
    23	/** Validates a POST /api/jobs request. `raw` is the body text as received. */
    24	export function parseCreateJob(contentType: string | undefined, raw: string | undefined): Parsed<NewJob> {
    25	  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
    26	  if (mediaType !== 'application/json') {
    27	    return fail([{ field: 'body', message: 'Content-Type must be application/json' }]);
    28	  }
    29	  if (raw === undefined) return fail([{ field: 'body', message: 'body is too large' }]);
    30	  let body: unknown;
    31	  try {
    32	    body = JSON.parse(raw);
    33	  } catch {
    34	    return fail([{ field: 'body', message: 'body must be valid JSON' }]);
    35	  }
    36	  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    37	    return fail([{ field: 'body', message: 'body must be a JSON object' }]);
    38	  }
    39	  const record = body as Record<string, unknown>;
    40	  const errors: FieldError[] = [];
    41	
    42	  for (const key of Object.keys(record)) {
    43	    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
    44	  }
    45	
    46	  let input = '';
    47	  const rawInput = record.input;
    48	  if (rawInput === undefined) {
    49	    errors.push({ field: 'input', message: 'is required' });
    50	  } else if (typeof rawInput !== 'string') {
    51	    errors.push({ field: 'input', message: 'must be a string' });
    52	  } else if (rawInput.length < 1 || rawInput.length > 1000) {
    53	    errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    54	  } else if (rawInput.trim().length === 0) {
    55	    errors.push({ field: 'input', message: 'must not be only whitespace' });
    56	  } else {
    57	    input = rawInput;
    58	  }
    59	
    60	  const steps = intField(record, 'steps', 1, 20, 5, errors);
    61	  const failAttempts = intField(record, 'failAttempts', 0, 5, 0, errors);
    62	
    63	  if (errors.length > 0) return fail(errors);
    64	  return { ok: true, value: { input, steps, failAttempts } };
    65	}
    66	
    67	function intField(record: Record<string, unknown>, name: string, min: number, max: number, dflt: number, errors: FieldError[]): number {
    68	  const value = record[name];
    69	  if (value === undefined) return dflt;
    70	  if (typeof value !== 'number' || !Number.isInteger(value)) {
    71	    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    72	    return dflt;
    73	  }
    74	  if (value < min || value > max) {
    75	    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    76	    return dflt;
    77	  }
    78	  return value;
    79	}
    80	
    81	function fail<T>(fields: FieldError[]): Parsed<T> {
    82	  return { ok: false, fields };
    83	}
